; rotate.asm -- chapter 27: eight on a line, the table turned
; generated by gen27.py
        INCLUDE "msx.inc"
        OUTPUT "rotate.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; Eight figures on lines 88 to 103. For 16 frames the table is sent as it is;
; then, for 48 frames, it is sent from entry k, k going up by 4 each frame
; and round from 7 to 0: the figures the VDP leaves out change places.
copy    EQU $C400               ; the entries twice ($D0 sent once)
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3800        ; the sprite patterns
        ld hl, patterns
        ld c, VDP_DATA
        ld b, 160
        otir
        ld hl, atts             ; the copy: the eight entries twice, so that
        ld de, copy             ; eight from any of them are in a row
        ld bc, 32
        ldir
        ld hl, atts
        ld bc, 32
        ldir
        VRAM_WRITE $1B00        ; the attributes
        ld hl, atts
        ld c, VDP_DATA
        ld b, 33
        otir
        VDP_REG 1, $C2          ; the display on, sprites of 16 x 16
        in a, (VDP_CTRL)        ; F cleared: the first wait ends with a paper
        ld e, 16
still:  call frame
        dec e
        jr nz, still
        ld e, 48
        ld d, 0                 ; k, times 4: the first entry sent
next:   ld a, d                 ;  5  k + 4, round 8: times 4, round 32
        add a, 16               ;  8
        and 31                  ;  8
        ld d, a                 ;  5
        call frame              ; the paper has ended
m0:     VRAM_WRITE $1B00        ; 40
        ld hl, copy             ; 11  the copy from entry k
        ld b, 0                 ;  8
        ld c, d                 ;  5
        add hl, bc              ; 12
        ld c, VDP_DATA          ;  8
        ld b, 32                ;  8  eight entries
        otir                    ; 23 a byte, 18 the last
m1:     dec e
        jr nz, next
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret
patterns:
        db $03, $07, $05, $07, $02, $1F, $3F, $37
        db $37, $37, $07, $06, $06, $06, $0E, $0E
        db $C0, $E0, $A0, $E0, $40, $F8, $FC, $EC
        db $EC, $EC, $E0, $60, $60, $60, $70, $70
        db $00, $07, $0F, $1F, $3F, $7F, $7F, $7F
        db $7F, $7F, $7F, $3F, $1F, $0F, $07, $00
        db $00, $E0, $F0, $F8, $FC, $FE, $FE, $FE
        db $FE, $FE, $FE, $FC, $F8, $F0, $E0, $00
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $07, $18, $20, $40, $46, $86, $80, $80
        db $80, $88, $47, $40, $20, $18, $07, $00
        db $E0, $18, $04, $02, $62, $61, $01, $01
        db $01, $11, $E2, $02, $04, $18, $E0, $00
        db $00, $07, $1F, $3F, $39, $79, $7F, $7F
        db $7F, $77, $38, $3F, $1F, $07, $00, $00
        db $00, $E0, $F8, $FC, $9C, $9E, $FE, $FE
        db $FE, $EE, $1C, $FC, $F8, $E0, $00, $00
atts:
        db $57, $08, $00, $01
        db $57, $26, $00, $01
        db $57, $44, $00, $01
        db $57, $62, $00, $01
        db $57, $80, $00, $01
        db $57, $9E, $00, $01
        db $57, $BC, $00, $01
        db $57, $DA, $00, $01
        db $D0
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
